process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import { chromium } from 'playwright';
import fs from 'fs';
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const HTML=Buffer.from('','base64').toString();
async function put(path, buf, msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'m', content:buf.toString('base64')};
  if(sha) body.sha=sha;
  const r2=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  console.log('put',path,r2.status);
}
async function main(){
  const out={};
  fs.writeFileSync('/tmp/maketas.html', HTML);
  const b=await chromium.launch();
  const ctx=await b.newContext({viewport:{width:1680,height:1400}});
  const p=await ctx.newPage();
  await p.goto('file:///tmp/maketas.html',{waitUntil:'networkidle',timeout:40000});
  await p.waitForTimeout(1500);
  await p.screenshot({path:'/tmp/m_sarasas.png'});
  out.sarasas='ok';
  // atidarom kortele
  const a=p.locator('a,tr').filter({hasText:'Josera'}).first();
  try{
    await p.locator('.pav a, td.pav a, a.atv').first().click();
    await p.waitForTimeout(1500);
    await p.screenshot({path:'/tmp/m_kortele.png'});
    out.kortele='ok';
  }catch(e){ out.kortele='nepavyko: '+String(e).slice(0,80); }
  // stiliu ištrauka
  out.spalvos=await p.evaluate(()=>{
    const s=getComputedStyle(document.body);
    const t=document.querySelector('table');
    const th=document.querySelector('th');
    const td=document.querySelector('td');
    return {
      body_bg:s.backgroundColor, body_font:s.fontFamily, body_size:s.fontSize,
      th_size: th?getComputedStyle(th).fontSize:'', th_pad: th?getComputedStyle(th).padding:'',
      th_color: th?getComputedStyle(th).color:'', th_bg: th?getComputedStyle(th).backgroundColor:'',
      td_pad: td?getComputedStyle(td).padding:'', td_size: td?getComputedStyle(td).fontSize:'',
      td_border: td?getComputedStyle(td).borderBottom:'',
    };
  });
  await b.close();
  for(const f of ['m_sarasas','m_kortele']){
    try{ await put('screenshots/'+f+'.png', fs.readFileSync('/tmp/'+f+'.png'), f); }catch(e){}
  }
  await put('analize/maketas.json', Buffer.from(JSON.stringify(out,null,2)),'maketas');
}
main().catch(async e=>{ await put('analize/maketas.json',Buffer.from(JSON.stringify({klaida:String(e)})),'err'); });
